name: Notify Dev Channel

on:
  push:
    branches:
      - master
    paths:
      - 'src/**'

permissions:
  contents: read
  pull-requests: write
  issues: write

jobs:
  notify:
    runs-on: ubuntu-latest
    if: startsWith(github.event.head_commit.message, 'Merge pull request #')
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Extract PR Number
        id: extract_pr
        run: |
          PR_NUMBER=$(echo "${{ github.event.head_commit.message }}" | grep -oP 'Merge pull request #\K[0-9]+')
          echo "PR_NUMBER=${PR_NUMBER}" >> $GITHUB_OUTPUT

      - name: Get PR Details
        id: get_pr_details
        if: steps.extract_pr.outputs.PR_NUMBER != ''
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const prNumber = ${{ steps.extract_pr.outputs.PR_NUMBER }};
            const pr = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: prNumber
            });

            // Extract linked issues from PR body
            const body = pr.data.body || '';
            const issueRegex = /(?:Closes|Fixes|Resolves)\s+#(\d+)/gi;
            const matches = [...body.matchAll(issueRegex)];
            const issueNumbers = matches.map(m => m[1]);

            // Store issue numbers in output
            core.setOutput('issue_numbers', JSON.stringify(issueNumbers));
            core.setOutput('pr_title', pr.data.title);

      - name: Comment on PR
        if: steps.extract_pr.outputs.PR_NUMBER != ''
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const prNumber = ${{ steps.extract_pr.outputs.PR_NUMBER }};

            const comment = `## 🧪 Your changes are now in the dev channel!

Your PR has been merged to master and is available for testing in the **dev channel**.

**Test your changes before the Tuesday release:**
📖 **[Dev Channel Documentation](https://github.com/homeassistant-ai/ha-mcp/blob/master/docs/dev-channel.md)**

Quick start: \`uvx ha-mcp-dev\`

### Docker
\`\`\`bash
docker run -p 8000:8000 ghcr.io/homeassistant-ai/ha-mcp:dev
\`\`\`

Thank you for contributing! Please help us ensure a stable release by testing in the dev channel.`;

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
              body: comment
            });

      - name: Comment on Linked Issues
        if: steps.get_pr_details.outputs.issue_numbers != '[]' && steps.get_pr_details.outputs.issue_numbers != ''
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const issueNumbers = JSON.parse('${{ steps.get_pr_details.outputs.issue_numbers }}');
            const prNumber = ${{ steps.extract_pr.outputs.PR_NUMBER }};

            for (const issueNumber of issueNumbers) {
              const comment = `## ✅ This issue has been addressed in the dev channel!

A fix for this issue has been merged to master (PR #${prNumber}) and is available for testing in the **dev channel**.

**Please test the fix before the Tuesday release:**
📖 **[Dev Channel Documentation](https://github.com/homeassistant-ai/ha-mcp/blob/master/docs/dev-channel.md)**

Quick start: \`uvx ha-mcp-dev\`

### Docker
\`\`\`bash
docker run -p 8000:8000 ghcr.io/homeassistant-ai/ha-mcp:dev
\`\`\`

Thank you for reporting this issue!`;

              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: issueNumber,
                body: comment
              });
            }
